"""Report exports: an interactive HTML dashboard, PDF and Word, from a scanner result.

Input is the JSON written by sfe.scanner.to_json, plus optional extra sections (for example a document review):

  sections = [{"title": str, "intro": str, "items": [{"status": "ok|gap|review|info", "title": str,
               "detail": str, "rule": str (optional), "evidence": str (optional)}]}]

HTML needs nothing. PDF needs Chrome or Chromium (set CHROME=/path) or WeasyPrint. Word needs python-docx.
Licence: Apache-2.0
"""
from __future__ import annotations

import html
import json
import os
import shutil
import subprocess
import tempfile
from pathlib import Path

from .config import Config

SEVS = ["BLOCK", "REVIEW", "WARN", "HUMAN", "WAIVED"]
SEV_TEXT = {"BLOCK": "Fix before launch", "REVIEW": "Needs a decision", "WARN": "Recommended fix",
            "HUMAN": "A person must check", "WAIVED": "Waived with a reason"}
SEV_COLOUR = {"BLOCK": "#b42318", "REVIEW": "#b54708", "WARN": "#8a6d00", "HUMAN": "#365a7a", "WAIVED": "#5f6b73"}
STATUS_TEXT = {"ok": "Found", "gap": "Missing", "review": "Check", "info": "Note"}
STATUS_COLOUR = {"ok": "#127a3f", "gap": "#b42318", "review": "#b54708", "info": "#365a7a"}


def build_model(cfg: Config, result: dict, rules_by_id: dict, sources: dict, sections: list | None = None) -> dict:
    groups = []
    for sev in SEVS:
        by_rule = {}
        for f in result.get("findings", []):
            if f["severity"] != sev:
                continue
            g = by_rule.setdefault(f["rule"], {"rule": f["rule"], "title": f["title"], "strength": f["strength"],
                                                "tier": f["tier"], "improvement": f["improvement"], "sources": f["sources"],
                                                "profiles": rules_by_id.get(f["rule"], {}).get("profiles", []),
                                                "why": str(rules_by_id.get(f["rule"], {}).get("rationale", "")).strip(),
                                                "items": []})
            g["items"].append({"where": f.get("where", ""), "detail": f.get("detail", ""), "waived": f.get("waived", "")})
        if by_rule:
            groups.append({"severity": sev, "rules": sorted(by_rule.values(), key=lambda g: g["rule"])})
    used = sorted({s for g in groups for r in g["rules"] for s in r["sources"]})
    return {"framework": cfg.short, "name": cfg.name, "site": cfg.site, "product": result.get("product") or "",
            "date": result.get("date", ""), "level": result.get("level", 1), "level_name": cfg.levels.get(result.get("level", 1), ""),
            "levels": cfg.levels, "verdict": result.get("verdict", ""), "counts": result.get("counts", {}),
            "in_scope": len(result.get("rules_in_scope", [])), "description_only": result.get("description_only", False),
            "groups": groups, "sections": sections or [],
            "sources": [{"id": s, "title": sources.get(s, {}).get("title", s), "url": sources.get(s, {}).get("url", ""),
                         "status": sources.get(s, {}).get("status", "")} for s in used]}


# --------------------------------------------------------------------------- HTML
CSS = """:root{--ink:#14232c;--muted:#51626c;--line:#d9e1e5;--paper:#f7f9fa;--card:#fff;--accent:ACCENT}
*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:15px/1.55 system-ui,-apple-system,"Segoe UI",Roboto,sans-serif}
header{background:var(--card);border-bottom:4px solid var(--accent);padding:22px 28px}header h1{margin:0 0 4px;font-size:1.55rem}
.meta{color:var(--muted);font-size:.9rem}.wrap{max-width:1100px;margin:0 auto;padding:20px 28px 60px}
.verdict{font-weight:700;font-size:1.05rem;margin:14px 0 0}
.counts{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:10px;margin:18px 0}
.count{background:var(--card);border:1px solid var(--line);border-top:4px solid var(--c);border-radius:8px;padding:10px 12px}
.count b{display:block;font-size:1.6rem;line-height:1.1}.count span{font-size:.82rem;color:var(--muted)}
.bar{display:flex;flex-wrap:wrap;gap:8px 16px;align-items:center;background:var(--card);border:1px solid var(--line);border-radius:8px;padding:10px 14px;margin:8px 0 18px}
.bar label{font-size:.9rem}.bar input[type=search]{flex:1;min-width:180px;padding:6px 9px;border:1px solid var(--line);border-radius:6px;font:inherit}
.bar button{font:inherit;padding:6px 12px;border:1px solid var(--line);background:#fff;border-radius:6px;cursor:pointer}
h2{margin:30px 0 10px;font-size:1.2rem}.rule{background:var(--card);border:1px solid var(--line);border-left:5px solid var(--c);border-radius:8px;padding:12px 16px;margin:10px 0}
.rule h3{margin:0 0 4px;font-size:1rem}.tag{display:inline-block;font-size:.75rem;font-weight:700;color:#fff;background:var(--c);border-radius:4px;padding:1px 7px;margin-right:6px}
.rule p{margin:6px 0}.rule ul{margin:6px 0 2px;padding-left:20px}.rule code{background:#eef2f4;padding:0 4px;border-radius:3px;font-size:.88em}
details summary{cursor:pointer;color:var(--muted);font-size:.88rem}.src a{color:var(--ink)}
.item{display:flex;gap:10px;align-items:flex-start;background:var(--card);border:1px solid var(--line);border-radius:8px;padding:10px 14px;margin:8px 0}
.st{flex:0 0 auto;font-size:.75rem;font-weight:700;color:#fff;border-radius:4px;padding:2px 8px;margin-top:2px}
.note{background:#fff8ec;border:1px solid #f0d9b5;border-radius:8px;padding:10px 14px;font-size:.9rem;margin-top:30px}
.hidden{display:none}footer{color:var(--muted);font-size:.85rem;margin-top:30px}
@media print{.bar,button{display:none}body{background:#fff}.rule,.item,.count{break-inside:avoid}details{display:block}details>summary{display:none}}
@media (max-width:700px){.counts{grid-template-columns:repeat(2,1fr)}}
"""

JS = """const q=document.getElementById('q'),boxes=[...document.querySelectorAll('[data-sevf]')],lv=document.getElementById('lv');
function apply(){const on=new Set(boxes.filter(b=>b.checked).map(b=>b.value)),t=(q.value||'').toLowerCase(),L=+lv.value;
document.querySelectorAll('.rule').forEach(r=>{const ok=on.has(r.dataset.sev)&&(+r.dataset.tier<=L)&&(!t||r.textContent.toLowerCase().includes(t));r.classList.toggle('hidden',!ok)});
document.querySelectorAll('section[data-sev]').forEach(s=>s.classList.toggle('hidden',!s.querySelector('.rule:not(.hidden)')));}
[q,lv,...boxes].forEach(e=>e.addEventListener('input',apply));document.getElementById('pr').addEventListener('click',()=>window.print());"""


def _e(s):
    return html.escape(str(s or ""))


def render_html(model: dict, accent: str = "#0f6e6e", for_print: bool = False) -> str:
    c = model["counts"]
    cards = "".join(f'<div class="count" style="--c:{SEV_COLOUR[s]}"><b>{c.get(s, 0)}</b><span>{s}: {SEV_TEXT[s]}</span></div>' for s in SEVS)
    bar = ""
    if not for_print:
        sevs = "".join(f'<label><input type="checkbox" data-sevf value="{s}" checked> {s}</label>' for s in SEVS)
        lvls = "".join(f'<option value="{k}"{" selected" if k == model["level"] else ""}>Up to level {k}: {_e(v)}</option>' for k, v in model["levels"].items())
        bar = (f'<div class="bar" role="search"><input id="q" type="search" placeholder="Search rules, files, words" aria-label="Search">'
               f'{sevs}<select id="lv" aria-label="Level">{lvls}</select><button id="pr" type="button">Print or save as PDF</button></div>')
    srcs = {s["id"]: s for s in model["sources"]}
    body = []
    for g in model["groups"]:
        sev = g["severity"]
        rs = []
        for r in g["rules"]:
            items = "".join(f'<li>{"<code>" + _e(i["where"]) + "</code> " if i["where"] else ""}{_e(i["detail"])}'
                            f'{" <em>(" + _e(i["waived"]) + ")</em>" if i["waived"] else ""}</li>' for i in r["items"])
            links = ", ".join(f'<a href="{_e(srcs[s]["url"])}">{_e(s)}</a>' if srcs.get(s, {}).get("url") else _e(s) for s in r["sources"])
            why = f'<details><summary>Why this rule</summary><p>{_e(r["why"])}</p></details>' if r["why"] else ""
            rs.append(f'<article class="rule" style="--c:{SEV_COLOUR[sev]}" data-sev="{sev}" data-tier="{r["tier"]}">'
                      f'<h3><span class="tag">{sev}</span>{_e(r["rule"])}: {_e(r["title"])}</h3>'
                      f'<div class="meta">{_e(r["strength"])} · level {r["tier"]} ({_e(model["levels"].get(r["tier"], ""))}) · profiles {_e(", ".join(r["profiles"]))}</div>'
                      f'<p><b>How to improve.</b> {_e(r["improvement"])}</p>{why}<ul>{items}</ul>'
                      f'<p class="src meta">Sources: {links}</p></article>')
        body.append(f'<section data-sev="{sev}"><h2>{sev}: {SEV_TEXT[sev]}</h2>{"".join(rs)}</section>')
    for sec in model["sections"]:
        its = "".join(f'<div class="item"><span class="st" style="background:{STATUS_COLOUR.get(i.get("status"), "#365a7a")}">'
                      f'{_e(STATUS_TEXT.get(i.get("status"), i.get("status")))}</span><div><b>{_e(i.get("title"))}</b>'
                      f'{" <span class=meta>(" + _e(i["rule"]) + ")</span>" if i.get("rule") else ""}'
                      f'<div>{_e(i.get("detail"))}</div>{"<div class=meta>" + _e(i["evidence"]) + "</div>" if i.get("evidence") else ""}</div></div>'
                      for i in sec.get("items", []))
        body.append(f'<section class="extra"><h2>{_e(sec["title"])}</h2><p class="meta">{_e(sec.get("intro", ""))}</p>{its}</section>')
    src_list = "".join(f'<li><b>{_e(s["id"])}</b>: {_e(s["title"])}{" (" + _e(s["status"][:160]) + ")" if s["status"] else ""}'
                       f'{" <a href=" + chr(34) + _e(s["url"]) + chr(34) + ">link</a>" if s["url"] else ""}</li>' for s in model["sources"])
    mode = " · description only (code not read)" if model["description_only"] else ""
    return ("<!DOCTYPE html>\n<html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">"
            f"<title>{_e(model['framework'])} report{': ' + _e(model['product']) if model['product'] else ''}</title>"
            f"<style>{CSS.replace('ACCENT', accent)}</style></head><body>"
            f"<header><h1>{_e(model['framework'])} report{': ' + _e(model['product']) if model['product'] else ''}</h1>"
            f"<div class=\"meta\">{_e(model['name'])} · level {model['level']} ({_e(model['level_name'])}) · {model['in_scope']} rules in scope · {_e(model['date'])}{mode}</div>"
            f"<p class=\"verdict\">{_e(model['verdict'])}</p></header><main class=\"wrap\"><div class=\"counts\">{cards}</div>{bar}"
            f"{''.join(body)}<h2>Sources cited</h2><ul class=\"src\">{src_list}</ul>"
            "<p class=\"note\">Automated checks find signs, not proof. A clean report does not mean the product is compliant. "
            "This report is not legal or regulatory advice.</p>"
            f"<footer>Generated with {_e(model['name'])} ({_e(model['framework'])}). {_e(model['site'])}</footer></main>"
            + ("" if for_print else f"<script>{JS}</script>") + "</body></html>\n")


# --------------------------------------------------------------------------- PDF
def find_chrome():
    env = os.environ.get("CHROME")
    if env and Path(env).exists():
        return env
    for n in ("google-chrome", "chromium", "chromium-browser", "chrome", "msedge"):
        p = shutil.which(n)
        if p:
            return p
    for p in ("/Applications/Google Chrome.app/Contents/MacOS/Google Chrome", r"C:\Program Files\Google\Chrome\Application\chrome.exe"):
        if Path(p).exists():
            return p
    return None


def render_pdf(html_text: str, pdf_path: Path) -> str:
    chrome = find_chrome()
    if chrome:
        with tempfile.TemporaryDirectory() as d:
            src = Path(d) / "report.html"
            src.write_text(html_text, encoding="utf-8")
            subprocess.run([chrome, "--headless=new", "--no-sandbox", "--disable-gpu", "--no-pdf-header-footer",
                            f"--print-to-pdf={pdf_path}", src.as_uri()], check=True, capture_output=True, timeout=120)
        return "chrome"
    try:
        import weasyprint  # type: ignore
        weasyprint.HTML(string=html_text).write_pdf(str(pdf_path))
        return "weasyprint"
    except ImportError:
        raise RuntimeError("PDF export needs Chrome or Chromium (set CHROME=/path) or `pip install weasyprint`.")


# --------------------------------------------------------------------------- Word
def render_docx(model: dict, path: Path, accent: str = "#0f6e6e") -> None:
    try:
        from docx import Document
        from docx.shared import Pt, RGBColor
    except ImportError:
        raise RuntimeError("Word export needs python-docx: pip install python-docx")
    rgb = lambda h: RGBColor.from_string(h.lstrip("#").upper())  # noqa: E731
    doc = Document()
    st = doc.styles["Normal"]
    st.font.name = "Calibri"
    st.font.size = Pt(11)
    doc.add_heading(f"{model['framework']} report{': ' + model['product'] if model['product'] else ''}", 0)
    doc.add_paragraph(f"{model['name']} · level {model['level']} ({model['level_name']}) · {model['in_scope']} rules in scope · {model['date']}"
                      + (" · description only" if model["description_only"] else ""))
    p = doc.add_paragraph()
    p.add_run(model["verdict"]).bold = True
    t = doc.add_table(rows=2, cols=len(SEVS))
    t.style = "Table Grid"
    for i, s in enumerate(SEVS):
        t.cell(0, i).text = s
        t.cell(1, i).text = str(model["counts"].get(s, 0))
        for run in t.cell(0, i).paragraphs[0].runs:
            run.bold = True
            run.font.color.rgb = rgb(SEV_COLOUR[s])
    srcs = {s["id"]: s for s in model["sources"]}
    for g in model["groups"]:
        doc.add_heading(f"{g['severity']}: {SEV_TEXT[g['severity']]}", 1)
        for r in g["rules"]:
            h = doc.add_heading(f"{r['rule']}: {r['title']}", 2)
            for run in h.runs:
                run.font.color.rgb = rgb(SEV_COLOUR[g["severity"]])
            doc.add_paragraph(f"{r['strength']} · level {r['tier']} · profiles {', '.join(r['profiles'])}").runs[0].italic = True
            q = doc.add_paragraph()
            q.add_run("How to improve. ").bold = True
            q.add_run(r["improvement"])
            if r["why"]:
                q = doc.add_paragraph()
                q.add_run("Why. ").bold = True
                q.add_run(r["why"])
            for i in r["items"]:
                doc.add_paragraph((f"{i['where']}: " if i["where"] else "") + i["detail"] + (f" ({i['waived']})" if i["waived"] else ""),
                                  style="List Bullet")
            doc.add_paragraph("Sources: " + ", ".join(f"{s} ({srcs[s]['url']})" if srcs.get(s, {}).get("url") else s for s in r["sources"]))
    for sec in model["sections"]:
        doc.add_heading(sec["title"], 1)
        if sec.get("intro"):
            doc.add_paragraph(sec["intro"])
        for i in sec.get("items", []):
            q = doc.add_paragraph(style="List Bullet")
            r1 = q.add_run(f"{STATUS_TEXT.get(i.get('status'), i.get('status'))}: ")
            r1.bold = True
            r1.font.color.rgb = rgb(STATUS_COLOUR.get(i.get("status"), "#365a7a"))
            q.add_run(f"{i.get('title', '')}" + (f" ({i['rule']})" if i.get("rule") else "") + f". {i.get('detail', '')}")
            if i.get("evidence"):
                q.add_run(f" {i['evidence']}").italic = True
    doc.add_heading("Sources cited", 1)
    for s in model["sources"]:
        doc.add_paragraph(f"{s['id']}: {s['title']}" + (f" {s['url']}" if s["url"] else ""), style="List Bullet")
    doc.add_paragraph("Automated checks find signs, not proof. A clean report does not mean the product is compliant. "
                      "This report is not legal or regulatory advice.").runs[0].italic = True
    doc.save(str(path))


def export(cfg: Config, result: dict, rules_by_id: dict, sources: dict, formats, out_dir: Path,
           sections: list | None = None, accent: str = "#0f6e6e", stem: str = "report") -> dict:
    out_dir = Path(out_dir)
    out_dir.mkdir(parents=True, exist_ok=True)
    model = build_model(cfg, result, rules_by_id, sources, sections)
    written = {}
    if "html" in formats:
        p = out_dir / f"{stem}.html"
        p.write_text(render_html(model, accent), encoding="utf-8")
        written["html"] = p
    if "pdf" in formats:
        p = out_dir / f"{stem}.pdf"
        render_pdf(render_html(model, accent, for_print=True), p)
        written["pdf"] = p
    if "docx" in formats:
        p = out_dir / f"{stem}.docx"
        render_docx(model, p, accent)
        written["docx"] = p
    if "json" in formats:
        p = out_dir / f"{stem}-model.json"
        p.write_text(json.dumps(model, indent=2, ensure_ascii=False), encoding="utf-8")
        written["json"] = p
    return written

files.engine/sfe/patterns.py:
"""Pattern matching over a code base: files, inline ignores, regex and dependency findings.

Lifted from CSEF tooling/scan.py (v0.14.1). tests/test_engine.py in CSEF keeps the two in step until scan.py
imports this module.
"""
from __future__ import annotations

import fnmatch
import json
import os
import re
from pathlib import Path

import yaml

SOURCE_EXT = {
    ".js", ".jsx", ".ts", ".tsx", ".mjs", ".cjs", ".vue", ".svelte", ".html", ".htm", ".css", ".scss", ".less",
    ".py", ".java", ".kt", ".kts", ".swift", ".m", ".dart", ".cs", ".go", ".rb", ".php",
    ".sql", ".json", ".yaml", ".yml", ".xml", ".plist", ".gd", ".lua", ".gradle", ".strings",
    ".po", ".arb", ".properties", ".toml", ".env",
    ".prefab", ".asset", ".unity", ".asmdef", ".tscn", ".tres", ".godot",          # Unity and Godot text assets
    ".c", ".cc", ".cpp", ".h", ".hpp", ".rs", ".scala", ".ex", ".exs", ".m", ".mm", ".rules",
}
SKIP_DIRS = {
    ".git", "node_modules", "dist", "build", ".next", ".nuxt", "out", "coverage", "vendor",
    "Pods", ".gradle", ".idea", ".vscode", "__pycache__", ".venv", "venv", "env", "Library",
    "Temp", "csef-report", "cses-report", ".csef", ".cses", "Logs", "obj", "UserSettings", "Build", "Builds", ".godot", "target",
}
SKIP_FILES = {
    "package-lock.json", "yarn.lock", "pnpm-lock.yaml", "poetry.lock", "Podfile.lock",
    "pubspec.lock", "composer.lock", "Cargo.lock",
}
MAX_FILE_BYTES = 1_000_000


def iter_files(repo: Path, manifest_names=(), skip_dirs=None):
    skip_dirs = SKIP_DIRS if skip_dirs is None else skip_dirs
    for dirpath, dirnames, filenames in os.walk(repo):
        dirnames[:] = [d for d in dirnames if d not in skip_dirs]
        for fn in filenames:
            if fn in SKIP_FILES or fn in manifest_names:
                continue
            p = Path(dirpath) / fn
            if p.suffix.lower() not in SOURCE_EXT and fn not in ("Podfile",):
                continue
            try:
                if p.stat().st_size > MAX_FILE_BYTES:
                    continue
            except OSError:
                continue
            yield p


def read_text(p: Path):
    try:
        return p.read_text(encoding="utf-8", errors="ignore")
    except OSError:
        return None


class Ignore:
    """Inline ignore comments, for example `csef-ignore: CORE-DAT-01 because ...`."""

    def __init__(self, token: str, aliases: dict | None = None):
        self.rx = re.compile(token + r":\s*([A-Z0-9, -]+?)(?:\s+(?:--|because|reason:)\s*(.*))?$", re.I) if token else None
        self.aliases = aliases or {}

    def check(self, lines, idx, rule_id) -> str | None:
        if not self.rx:
            return None
        for j in (idx, idx - 1):
            if 0 <= j < len(lines):
                m = self.rx.search(lines[j])
                if m and rule_id in [self.aliases.get(x.strip(), x.strip()) for x in m.group(1).split(",")]:
                    return (m.group(2) or "no reason given").strip()
        return None


def compile_pattern(p):
    flags = re.I if "i" in str(p.get("flags", "")) else 0
    return re.compile(p["pattern"], flags | re.M)


def regex_findings(rule, pat, files_cache, repo: Path, ignore: "Ignore | None" = None):
    rx = compile_pattern(pat)
    globs = pat.get("globs")
    out = []
    for rel, lines, text in files_cache:
        if globs and not any(fnmatch.fnmatch(Path(rel).name, g) or fnmatch.fnmatch(rel, g) for g in globs):
            continue
        if not rx.search(text):
            continue
        for i, line in enumerate(lines):
            if rx.search(line):
                out.append((rel, i + 1, line.strip()[:160], (ignore.check(lines, i, rule["id"]) if ignore else None)))
                if len(out) > 25:
                    return out
    return out


def collect_dependencies(repo: Path, skip_dirs=None):
    skip_dirs = SKIP_DIRS if skip_dirs is None else skip_dirs
    deps = {}  # name -> file
    for dirpath, dirnames, filenames in os.walk(repo):
        dirnames[:] = [d for d in dirnames if d not in skip_dirs]
        for fn in filenames:
            p = Path(dirpath) / fn
            rel = str(p.relative_to(repo))
            try:
                if fn == "package.json":
                    data = json.loads(p.read_text(encoding="utf-8"))
                    for k in ("dependencies", "devDependencies", "peerDependencies", "optionalDependencies"):
                        for name in (data.get(k) or {}):
                            deps.setdefault(name, rel)
                elif fn.startswith("requirements") and fn.endswith(".txt"):
                    for ln in p.read_text(encoding="utf-8").splitlines():
                        m = re.match(r"\s*([A-Za-z0-9_.\-]+)", ln)
                        if m and not ln.strip().startswith("#"):
                            deps.setdefault(m.group(1).lower(), rel)
                elif fn == "pyproject.toml":
                    for m in re.finditer(r'^\s*"?([A-Za-z0-9_.\-]+)\s*(?:[<>=~!\[]|"|\s*=)', p.read_text(encoding="utf-8"), re.M):
                        deps.setdefault(m.group(1).lower(), rel)
                elif fn == "Podfile":
                    for m in re.finditer(r"pod\s+['\"]([^'\"/]+)", p.read_text(encoding="utf-8")):
                        deps.setdefault(m.group(1), rel)
                elif fn.endswith((".gradle", ".gradle.kts")):
                    for m in re.finditer(r"['\"]([a-zA-Z0-9_.\-]+:[a-zA-Z0-9_.\-]+)(?::[^'\"]*)?['\"]", p.read_text(encoding="utf-8")):
                        deps.setdefault(m.group(1), rel)
                elif fn == "manifest.json" and p.parent.name == "Packages":  # Unity Package Manager
                    data = json.loads(p.read_text(encoding="utf-8"))
                    for name in (data.get("dependencies") or {}):
                        deps.setdefault(name, rel)
                elif fn.endswith("Dependencies.xml"):  # Unity External Dependency Manager (Android and iOS SDKs)
                    t = p.read_text(encoding="utf-8")
                    for m in re.finditer(r'androidPackage\s+spec="([^":]+:[^":]+)', t):
                        deps.setdefault(m.group(1), rel)
                    for m in re.finditer(r'iosPod\s+name="([^"]+)"', t):
                        deps.setdefault(m.group(1), rel)
                elif fn == "pom.xml":
                    t = p.read_text(encoding="utf-8")
                    for m in re.finditer(r"<groupId>([^<]+)</groupId>\s*<artifactId>([^<]+)</artifactId>", t):
                        deps.setdefault(f"{m.group(1).strip()}:{m.group(2).strip()}", rel)
                elif fn.endswith((".csproj", ".fsproj")) or fn in ("packages.config", "Directory.Packages.props"):
                    for m in re.finditer(r'(?:PackageReference|PackageVersion|package)\s+(?:Include|id)="([^"]+)"', p.read_text(encoding="utf-8"), re.I):
                        deps.setdefault(m.group(1), rel)
                elif fn == "go.mod":
                    for m in re.finditer(r"^\s*(?:require\s+)?([\w.\-]+\.[\w.\-/]+)\s+v[\d.]+", p.read_text(encoding="utf-8"), re.M):
                        deps.setdefault(m.group(1), rel)
                elif fn == "Cargo.toml":
                    t = p.read_text(encoding="utf-8")
                    sec = re.search(r"^\[dependencies\]([\s\S]*?)(^\[|\Z)", t, re.M)
                    for m in re.finditer(r"^\s*([A-Za-z0-9_\-]+)\s*=", sec.group(1) if sec else "", re.M):
                        deps.setdefault(m.group(1), rel)
                elif fn == "composer.json":
                    data = json.loads(p.read_text(encoding="utf-8"))
                    for k in ("require", "require-dev"):
                        for name in (data.get(k) or {}):
                            deps.setdefault(name, rel)
                elif fn == "Gemfile":
                    for m in re.finditer(r"^\s*gem\s+['\"]([^'\"]+)", p.read_text(encoding="utf-8"), re.M):
                        deps.setdefault(m.group(1), rel)
                elif fn == "Package.swift":
                    for m in re.finditer(r'\.package\s*\(\s*(?:name:\s*"[^"]*",\s*)?url:\s*"[^"]*/([^/"]+?)(?:\.git)?"', p.read_text(encoding="utf-8")):
                        deps.setdefault(m.group(1), rel)
                elif fn == "pubspec.yaml":
                    data = yaml.safe_load(p.read_text(encoding="utf-8")) or {}
                    for k in ("dependencies", "dev_dependencies"):
                        for name in (data.get(k) or {}):
                            deps.setdefault(name, rel)
            except (OSError, ValueError, yaml.YAMLError):
                continue
    return deps


def dependency_findings(pat, deps):
    names = pat.get("names", [])
    lower = {k.lower(): (k, v) for k, v in deps.items()}
    hits = []
    for n in names:
        if n.lower() in lower:
            k, f = lower[n.lower()]
            hits.append((f, k))
    return hits

files.engine/sfe/scanner.py:
"""A generic scanner: which rules apply to a product, what the code and the manifest show, and the report.

A framework supplies its rules, its manifest checks (name -> function) and its config. Severities:

  BLOCK   a MUST rule with a high-confidence finding
  REVIEW  a MUST rule with a medium-confidence finding
  WARN    a SHOULD rule with a finding
  HUMAN   a rule in scope that only a person can check (detection: manual, or no finding to show either way)
  WAIVED  a finding covered by an inline ignore comment or a dated waiver in the manifest
"""
from __future__ import annotations

import datetime as dt
import json
from dataclasses import asdict, dataclass, field
from pathlib import Path

from .config import Config
from .patterns import Ignore, collect_dependencies, dependency_findings, iter_files, read_text, regex_findings

SEVERITY_ORDER = ["BLOCK", "REVIEW", "WARN", "HUMAN", "WAIVED"]


@dataclass
class Finding:
    rule: str
    severity: str
    title: str
    strength: str
    tier: int
    where: str = ""
    detail: str = ""
    improvement: str = ""
    sources: list = field(default_factory=list)
    waived: str = ""


def expand_features(cfg: Config, features) -> set:
    out = set()
    for f in features or []:
        out |= set(cfg.feature_groups.get(f, [f]))
    return out


def in_scope(cfg: Config, rule, manifest: dict | None, level: int) -> bool:
    if rule["tier"] > level:
        return False
    m = manifest or {}
    profiles = set(m.get("profiles") or ["core"]) | {"core"}
    if not set(rule["profiles"]) & profiles:
        return False
    dims = rule.get(cfg.dimension_key, ["all"])
    declared = set(m.get(cfg.dimension_key) or [])
    if dims != ["all"] and declared and not set(dims) & declared:
        return False
    feats = set(rule.get("features") or [])
    if feats and not feats & expand_features(cfg, m.get("features")):
        return False
    return True


def _waiver(manifest, rule_id, today):
    for w in (manifest or {}).get("waivers", []) or []:
        if w.get("rule") == rule_id:
            until = w.get("until")
            if until and str(until) < today.isoformat():
                continue
            return f"waiver: {w.get('reason', 'no reason given')}" + (f" (until {until})" if until else "")
    return None


def run(cfg: Config, repo: Path, rules: list, manifest: dict | None, level: int = 1, *, manifest_checks: dict,
        ignore: Ignore | None = None, description_only: bool = False, today: dt.date | None = None) -> dict:
    today = today or dt.date.today()
    repo = Path(repo)
    files_cache = []
    deps = {}
    if not description_only:
        for p in iter_files(repo, cfg.manifest_names):
            t = read_text(p)
            if t is not None:
                files_cache.append((str(p.relative_to(repo)), t.splitlines(), t))
        deps = collect_dependencies(repo)
    findings: list[Finding] = []
    in_scope_ids = []
    for r in sorted(rules, key=lambda r: r["id"]):
        if not in_scope(cfg, r, manifest, level):
            continue
        in_scope_ids.append(r["id"])
        base = dict(rule=r["id"], title=r["title"], strength=r["level"], tier=r["tier"],
                    improvement=r["improvement"].strip(), sources=list(r["sources"]))
        hit = False
        det = r.get("detection") or {}
        for p in det.get("patterns", []) or []:
            conf = p.get("confidence", "medium")
            sev = "WARN" if r["level"] == "SHOULD" else ("BLOCK" if conf == "high" else "REVIEW")
            if p["type"] == "regex" and not description_only:
                for rel, line, text, ign in regex_findings(r, p, files_cache, repo, ignore):
                    hit = True
                    w = ign and f"inline: {ign}"
                    findings.append(Finding(severity="WAIVED" if w else sev, where=f"{rel}:{line}", detail=text, waived=w or "", **base))
            elif p["type"] == "dependency" and not description_only:
                for f, name in dependency_findings(p, deps):
                    hit = True
                    findings.append(Finding(severity=sev, where=f, detail=f"dependency {name}", **base))
            elif p["type"] == "manifest":
                fn = manifest_checks[p["check"]]
                for msg in fn(manifest, repo, p) or []:
                    hit = True
                    findings.append(Finding(severity=sev, where="manifest", detail=msg, **base))
        if not hit and det.get("method") in ("manual", "mixed"):
            findings.append(Finding(severity="HUMAN", detail=det.get("human", "Check by hand and keep the evidence."), **base))
    for f in findings:
        if f.severity in ("BLOCK", "REVIEW", "WARN"):
            w = _waiver(manifest, f.rule, today)
            if w:
                f.severity, f.waived = "WAIVED", w
    findings.sort(key=lambda f: (SEVERITY_ORDER.index(f.severity), f.rule, f.where))
    counts = {s: sum(1 for f in findings if f.severity == s) for s in SEVERITY_ORDER}
    return {"level": level, "rules_in_scope": in_scope_ids, "findings": findings, "counts": counts,
            "date": today.isoformat(), "description_only": description_only}


def verdict(result) -> str:
    c = result["counts"]
    if c["BLOCK"]:
        return "Not ready: fix the BLOCK items first."
    if c["REVIEW"] or c["WARN"]:
        return "Review needed: no blocking finding, but items need a decision."
    return "No automated finding. The HUMAN items still need a person and evidence."


def render_markdown(cfg: Config, result, sources: dict, product: str = "") -> str:
    c = result["counts"]
    lines = [f"# {cfg.short} report{': ' + product if product else ''}", "",
             f"Level {result['level']} ({cfg.levels[result['level']]}) · {len(result['rules_in_scope'])} rules in scope · {result['date']}"
             + (" · description only (code not read)" if result["description_only"] else ""), "",
             f"**{verdict(result)}**", "",
             "| " + " | ".join(SEVERITY_ORDER) + " |", "|" + "---|" * len(SEVERITY_ORDER),
             "| " + " | ".join(str(c[s]) for s in SEVERITY_ORDER) + " |", ""]
    for sev in SEVERITY_ORDER:
        items = [f for f in result["findings"] if f.severity == sev]
        if not items:
            continue
        lines += [f"## {sev}", ""]
        last = None
        for f in items:
            if f.rule != last:
                if last is not None:
                    lines.append("")
                srcs = ", ".join(f"[{s}]({sources[s]['url']})" if sources.get(s, {}).get("url") else s for s in f.sources)
                lines += [f"### {f.rule}: {f.title} ({f.strength}, level {f.tier})", "", f"How to improve: {f.improvement}", "",
                          f"Sources: {srcs}", ""]
                last = f.rule
            loc = f"`{f.where}` " if f.where else ""
            lines.append(f"- {loc}{f.detail}" + (f" ({f.waived})" if f.waived else ""))
        lines.append("")
    lines += ["---", "", f"{cfg.name} ({cfg.short}). Automated checks find signs, not proof. "
              "This report is not legal or regulatory advice.", ""]
    return "\n".join(lines)


def to_json(cfg: Config, result, product: str = "") -> str:
    d = dict(result)
    d["findings"] = [asdict(f) for f in result["findings"]]
    d["framework"] = cfg.short
    d["product"] = product
    d["verdict"] = verdict(result)
    return json.dumps(d, indent=2, ensure_ascii=False) + "\n"


def to_sarif(cfg: Config, result, rules_by_id: dict) -> str:
    level = {"BLOCK": "error", "REVIEW": "warning", "WARN": "note"}
    res = []
    for f in result["findings"]:
        if f.severity not in level:
            continue
        loc = {}
        if ":" in f.where and f.where != "manifest":
            path, _, line = f.where.rpartition(":")
            loc = {"locations": [{"physicalLocation": {"artifactLocation": {"uri": path}, "region": {"startLine": int(line)}}}]}
        res.append({"ruleId": f.rule, "level": level[f.severity], "message": {"text": f"{f.title}. {f.detail}"}, **loc})
    used = sorted({f.rule for f in result["findings"]})
    sarif = {"version": "2.1.0", "$schema": "https://json.schemastore.org/sarif-2.1.0.json",
             "runs": [{"tool": {"driver": {"name": cfg.short, "informationUri": cfg.site or cfg.repo,
                                           "rules": [{"id": i, "shortDescription": {"text": rules_by_id[i]["title"]}} for i in used]}},
                       "results": res}]}
    return json.dumps(sarif, indent=2, ensure_ascii=False) + "\n"

files.tooling/checks.py:
"""HDSF manifest checks: what hdsf.yaml says, or fails to say.

Each check takes (manifest, repo, pattern) and returns a list of problems (empty = fine). The rules in
framework/rules.yaml name these checks. Licence: Apache-2.0
"""
from __future__ import annotations

import datetime as dt
import re
from pathlib import Path

EEA = {"EU", "EEA", "AT", "BE", "BG", "HR", "CY", "CZ", "DK", "EE", "FI", "FR", "DE", "GR", "EL", "HU", "IE", "IT", "LV",
       "LT", "LU", "MT", "NL", "PL", "PT", "RO", "SK", "SI", "ES", "SE", "IS", "LI", "NO"}
EEA_REGION = re.compile(r"(^eu\b|\beu-|-eu\b|europe|frankfurt|ireland|dublin|paris|stockholm|milan|madrid|lisbon|"
                        r"amsterdam|warsaw|vienna|brussels|helsinki|copenhagen|oslo)", re.I)
# Adequacy decisions and other Chapter V tools accepted as a recorded transfer tool.
TRANSFER_TOOLS = {"adequacy", "scc", "bcr", "derogation", "dpf"}
MEDICAL_WORDS = re.compile(r"\b(diagnos\w*|treat(s|ment|ing)?|therap\w*|cure\w*|monitor\w* (a |the )?(disease|condition)|"
                           r"predict\w* (the )?(risk|disease)|dose|dosing|detect\w* (cancer|disease|arrhythmia|atrial))\b", re.I)
DEVICE_KINDS = {"mdsw", "ivd", "annex_xvi"}
VALID_KINDS = DEVICE_KINDS | {"none", "undecided"}
REVIEW_MAX_DAYS = 400


def _get(m, path, default=None):
    cur = m or {}
    for k in path.split("."):
        if not isinstance(cur, dict):
            return default
        cur = cur.get(k)
    return default if cur is None else cur


def _exists(repo: Path, value) -> bool:
    if not value:
        return False
    v = str(value)
    if v.startswith(("http://", "https://")):
        return True
    return (Path(repo) / v).exists()


def _need_doc(m, repo, key, what):
    v = _get(m, key)
    if not v:
        return [f"{key} is not set: link {what}"]
    if not _exists(repo, v):
        return [f"{key} points to {v}, which does not exist"]
    return []


def _features(m):
    return set(_get(m, "features", []) or [])


def _kind(m):
    return _get(m, "qualification.medical_device")


# --------------------------------------------------------------------------- checks
def manifest_missing(m, repo, p):
    return [] if m else ["no hdsf.yaml found: copy templates/hdsf.yaml to the repository root"]


def intended_purpose_missing(m, repo, p):
    t = str(_get(m, "intended_purpose", "")).strip()
    if len(t) < 40:
        return ["intended_purpose is missing or too short to decide the qualification (one or two full sentences)"]
    return []


def qualification_missing(m, repo, p):
    k = _kind(m)
    if k is None:
        return ["qualification.medical_device is not set (none, mdsw, ivd, annex_xvi)"]
    if k not in VALID_KINDS:
        return [f"qualification.medical_device has an unknown value: {k}"]
    if k == "undecided":
        return ["qualification.medical_device is 'undecided': decide before launch"]
    if k in DEVICE_KINDS and "M" not in set(_get(m, "profiles", []) or []):
        return [f"qualification.medical_device is {k}, but profile M is not declared"]
    return []


def qualification_rationale_missing(m, repo, p):
    if _kind(m) in (None, "undecided"):
        return []
    return _need_doc(m, repo, "qualification.rationale", "the written qualification reasoning (templates/qualification.md)")


def wellness_purpose_sounds_medical(m, repo, p):
    if _kind(m) != "none":
        return []
    t = str(_get(m, "intended_purpose", ""))
    hits = sorted({x.group(0).lower() for x in MEDICAL_WORDS.finditer(t)})
    if hits:
        return [f"intended_purpose uses medical wording ({', '.join(hits)}) while qualification.medical_device is none: check the qualification or the wording"]
    return []


def device_class_missing(m, repo, p):
    k = _kind(m)
    if k not in DEVICE_KINDS:
        return []
    c = _get(m, "qualification.class")
    allowed = {"mdsw": {"I", "IIa", "IIb", "III"}, "annex_xvi": {"I", "IIa", "IIb", "III"}, "ivd": {"A", "B", "C", "D"}}[k]
    if c not in allowed:
        return [f"qualification.class must be one of {sorted(allowed)} for {k}"]
    out = []
    if not (k == "mdsw" and c == "I") and not (k == "ivd" and c == "A") and not _get(m, "qualification.notified_body"):
        out.append(f"class {c} needs a notified body: set qualification.notified_body (or 'planned')")
    return out


def device_docs_missing(m, repo, p):
    if _kind(m) not in DEVICE_KINDS:
        return []
    return _need_doc(m, repo, "clinical.qms", "the quality management system manual")


def clinical_evaluation_missing(m, repo, p):
    if _kind(m) not in DEVICE_KINDS:
        return []
    return (_need_doc(m, repo, "clinical.evaluation", "the clinical or performance evaluation")
            + _need_doc(m, repo, "clinical.pms_plan", "the post-market surveillance plan"))


def art9_condition_missing(m, repo, p):
    purposes = _get(m, "data.purposes", []) or []
    if not purposes:
        return ["data.purposes is empty: list each purpose with its basis (Art. 6) and art9 condition (Art. 9(2))"]
    out = []
    for i, x in enumerate(purposes):
        name = x.get("name", f"#{i + 1}") if isinstance(x, dict) else str(x)
        if not isinstance(x, dict) or not x.get("basis") or not x.get("art9"):
            out.append(f"purpose '{name}' lacks basis or art9")
        elif str(x.get("art9")).lower() in ("none", "n/a", "no"):
